precision highp float;
attribute vec4 position;
attribute float transparency;
uniform mat4 ProjectionMatrix;
varying vec2 fragCoord;
varying float inputAlpha;
void main(void)
{
    gl_Position = ProjectionMatrix * vec4(position.xy, 0.0, 1.0);
    fragCoord = vec2(position.z, position.w);
    inputAlpha = transparency;
}

#extension GL_OES_standard_derivatives : enable
precision mediump float;
uniform vec4 inputColor;
varying vec2 fragCoord;
varying float inputAlpha;
vec2 center = vec2(0.5, 0.5);
const float radius = 0.5;
const float gradLength = 0.4;
const float alphaRange = 0.93;
void main(void)
{
    float distY = abs(center.y - fragCoord.y);
    float gradAlpha = clamp(1.0 - alphaRange / gradLength * (gradLength - (radius - distY)), 0.0, 1.0);
    float dist = distance(center, fragCoord);
    float circleAlpha = (radius - dist) / abs(radius - dist);
    float distX = abs(center.x - fragCoord.x);
    float smoothAlpha = 1.0 - smoothstep(radius - fwidth(dist), radius, distX);
    float alpha = inputAlpha * gradAlpha * circleAlpha * smoothAlpha;
    gl_FragColor = vec4(inputColor.xyz, 1.0) * alpha;
}

